START TRANSACTION;
ALTER TABLE work."Tasks" ADD "LastWorkerId" character varying(100);

CREATE TABLE audit."ExecutorEvents" (
    "Id" uuid NOT NULL,
    "Sequence" bigint GENERATED BY DEFAULT AS IDENTITY,
    "ExecutorId" uuid NOT NULL,
    "Action" character varying(32) NOT NULL,
    "ActorId" uuid NOT NULL,
    "OccurredAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_ExecutorEvents" PRIMARY KEY ("Id")
);

CREATE TABLE work."Executors" (
    "Id" uuid NOT NULL,
    "Name" character varying(100) NOT NULL,
    "NormalizedName" character varying(100) NOT NULL,
    "Status" character varying(16) NOT NULL,
    "CredentialHash" character varying(64) NOT NULL,
    "AllowedTypes" character varying(256) NOT NULL,
    "CreatedBy" uuid NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CredentialRotatedAt" timestamp with time zone,
    "RevokedAt" timestamp with time zone,
    "RevokedBy" uuid,
    "LastSeenAt" timestamp with time zone,
    "State" character varying(16) NOT NULL,
    "WorkerVersion" character varying(32),
    CONSTRAINT "PK_Executors" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_Executors_Hash" CHECK ("CredentialHash" ~ '^[0-9a-f]{64}$'),
    CONSTRAINT "CK_Executors_Ids" CHECK ("Id" <> '00000000-0000-0000-0000-000000000000'::uuid AND "CreatedBy" <> '00000000-0000-0000-0000-000000000000'::uuid),
    CONSTRAINT "CK_Executors_Revoked" CHECK (("Status" = 'Revoked') = ("RevokedAt" IS NOT NULL AND "RevokedBy" IS NOT NULL)),
    CONSTRAINT "CK_Executors_State" CHECK ("State" IN ('Offline','Idle','Busy','Draining')),
    CONSTRAINT "CK_Executors_Status" CHECK ("Status" IN ('Active','Revoked')),
    CONSTRAINT "CK_Executors_Types" CHECK (length(btrim("AllowedTypes")) > 0)
);

CREATE INDEX "IX_ExecutorEvents_ExecutorId_OccurredAt" ON audit."ExecutorEvents" ("ExecutorId", "OccurredAt");

CREATE UNIQUE INDEX "IX_ExecutorEvents_Sequence" ON audit."ExecutorEvents" ("Sequence");

CREATE UNIQUE INDEX "IX_Executors_NormalizedName" ON work."Executors" ("NormalizedName");

INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
VALUES ('20261021205430_AddExecutors', '10.0.8');

COMMIT;

